code = f'''"""Transform: Two 4x4 patterns separated by column of 5s.
Check for overlap (same cells both non-zero).
If overlap exists, output only left pattern.
Otherwise, combine: left values where left!=0, then right where right!=0.
"""

def transform(grid):
    left_grid = [row[:4] for row in grid]
    right_grid = [row[5:] for row in grid]
    has_overlap = any(left_grid[r][c] != 0 and right_grid[r][c] != 0 for r in range(4) for c in range(4))
    if has_overlap:
        return left_grid
    output = []
    for r in range(4):
        row_out = []
        for c in range(4):
            if left_grid[r][c] != 0:
                row_out.append(left_grid[r][c])
            elif right_grid[r][c] != 0:
                row_out.append(right_grid[r][c])
            else:
                row_out.append(0)
        output.append(row_out)
    return output

